                         results.AppendLine($"- {text}");
                         count++;
                     }
                 }
             }

             var output = results.Length > 0
                 ? results.ToString()
                 : "No results found. Try a different or more specific query.";

             return output;
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     },
     "search_web",
     "Search the web for information on a topic. Returns relevant snippets.");

 AIFunction saveNote = AIFunctionFactory.Create(
     ([Description("A short title for the note")] string title,
      [Description("The note content to save")] string content) =>
     {
         notebook.Add(title, content);

         Console.ForegroundColor = ConsoleColor.DarkYellow;
         Console.WriteLine($"  📝 Note saved: {title}");
         Console.ResetColor();

         return $"Note '{title}' saved successfully. You now have {notebook.Count} note(s).";
     },
     "save_note",
     "Save a research note with a title and content for later reference.");

 AIFunction readNotes = AIFunctionFactory.Create(
     () =>
     {
         if (notebook.Count == 0)
             return "No notes saved yet.";

         return notebook.GetAllFormatted();
     },
     "read_notes",
     "Read all saved research notes.");

 // --- Build the agent ---------------------------------------------------------

 IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 var tools = new List<AITool> { searchWeb, saveNote, readNotes };

 var instructions = """
     You are a research agent. Your job is to thoroughly research a topic the user
     gives you and produce a well-structured summary.

     Follow this workflow:
     1. Break the topic into 2-3 key sub-questions.
     2. Use the search_web tool to find information for each sub-question.
     3. Use the save_note tool to record important findings as you go.
     4. After gathering enough information, use read_notes to review your findings.
     5. Produce a final summary that synthesizes everything, citing the sources you found.

     Be thorough but concise. If a search returns no results, try rephrasing the query.
     """;

 var agent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 // --- Run the agent -----------------------------------------------------------

 Console.ForegroundColor = ConsoleColor.Green;
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║         🔬 Research Agent                ║");
 Console.WriteLine("╠══════════════════════════════════════════╣");
 Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.ResetColor();

 while (true)
 {
     Console.WriteLine();
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("Topic: ");
     Console.ResetColor();

     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     notebook.Clear();

     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("Researching... (the agent will search and take notes)\n");
     Console.ResetColor();

     try
     {
         var runOptions = new ChatClientAgentRunOptions(new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
         });

         var session = await agent.CreateSessionAsync();
         var response = await agent.RunAsync(topic, session, runOptions);

         Console.ForegroundColor = ConsoleColor.White;
         Console.WriteLine("\n═══ Research Summary ═══\n");
         Console.ResetColor();
         Console.WriteLine(response.Text);
     }
     catch (Exception ex)
     {
         Console.ForegroundColor = ConsoleColor.Red;
         Console.WriteLine($"Error: {ex.Message}");
         Console.ResetColor();
     }
 }

 Console.WriteLine("Goodbye!");

 // --- Notebook helper ---------------------------------------------------------

 internal sealed class ResearchNotebook
 {
     private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

     public int Count => _notes.Count;

     public void Add(string title, string content)
         => _notes.Add((title, content, DateTime.UtcNow));

     public void Clear() => _notes.Clear();

     public string GetAllFormatted()
     {
         var sb = new StringBuilder();
         for (var i = 0; i < _notes.Count; i++)
         {
             var (title, content, ts) = _notes[i];
             sb.AppendLine($"### Note {i + 1}: {title}");
             sb.AppendLine(content);
             sb.AppendLine();
         }
         return sb.ToString();
     }
 }

